use std::fs

fn prec(op: string) -> int {
    if op == "^" { return 3 }
    if op == "*" || op == "/" { return 2 }
    if op == "+" || op == "-" { return 1 }
    0
}

fn convert(line: string) -> string {
    let cs: Vec<char> = line.chars().collect()
    let n: int = cs.len() as int
    let mut out: Vec<string> = []
    let mut st: Vec<string> = []
    let mut expect = true
    let mut i: int = 0
    while i < n {
        let c = cs[i as usize]
        if c == ' ' || c == '\t' || c == '\r' {
            i += 1
        } else if c >= '0' && c <= '9' {
            if !expect { return "error" }
            let mut num = ""
            while i < n && cs[i as usize] >= '0' && cs[i as usize] <= '9' {
                num = num + cs[i as usize].to_string()
                i += 1
            }
            out.push(num)
            expect = false
        } else if c == '(' {
            if !expect { return "error" }
            st.push("(")
            i += 1
        } else if c == ')' {
            if expect { return "error" }
            let mut found = false
            while st.len() > 0 {
                let t = st.pop().unwrap_or("")
                if t == "(" {
                    found = true
                    break
                }
                out.push(t)
            }
            if !found { return "error" }
            i += 1
        } else if c == '+' || c == '-' || c == '*' || c == '/' || c == '^' {
            if expect { return "error" }
            let op = c.to_string()
            let p = prec(op)
            let mut go = true
            while go && st.len() > 0 {
                let top = st[st.len() - 1]
                let tp = prec(top)
                if top != "(" && (tp > p || (tp == p && op != "^")) {
                    out.push(st.pop().unwrap_or(""))
                } else {
                    go = false
                }
            }
            st.push(op)
            expect = true
            i += 1
        } else {
            return "error"
        }
    }
    if expect { return "error" }
    while st.len() > 0 {
        let t = st.pop().unwrap_or("")
        if t == "(" { return "error" }
        out.push(t)
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(convert(line))
    }
}

